import type { StoredObject } from "@stallion/client-store";
import type { LiveObjects } from "@stallion/client-sync";
import { afterEach, expect, test, vi } from "vitest";
import { createSurface, PAPER } from "./surface";
import type { DrawingSource } from "./sync";

const stored: StoredObject = {
  tile: { level: 0, tx: 0, ty: 0 },
  object: {
    type: "Stroke",
    objectId: "000000000aaaaaaaaaaaa",
    nativeZoom: 0,
    bbox: { minX: 0, minY: 0, maxX: 10, maxY: 10 },
    colour: 0,
    size: "Medium",
    points: [
      [1, 1, 0.5],
      [8, 8, 0.5],
    ],
  },
};

afterEach(() => vi.unstubAllGlobals());

test("each frame paints the paper before any stroke", () => {
  const calls: string[] = [];
  const context = {
    setTransform: () => undefined,
    clearRect: () => calls.push("clearRect"),
    fillRect: function (this: { fillStyle: string }) {
      calls.push(`fillRect ${this.fillStyle}`);
    },
    fill: function (this: { fillStyle: string }) {
      calls.push(`fill ${this.fillStyle}`);
    },
    fillStyle: "",
  };
  const listen = { addEventListener: () => undefined, removeEventListener: () => undefined };
  vi.stubGlobal("window", { ...listen, devicePixelRatio: 1 });
  vi.stubGlobal("localStorage", { getItem: () => null, setItem: () => undefined });
  const frames: FrameRequestCallback[] = [];
  vi.stubGlobal("requestAnimationFrame", (callback: FrameRequestCallback) => frames.push(callback));
  vi.stubGlobal("cancelAnimationFrame", () => undefined);
  vi.stubGlobal(
    "ResizeObserver",
    class {
      observe() {}
      disconnect() {}
    },
  );
  vi.stubGlobal(
    "Path2D",
    class {
      moveTo() {}
      lineTo() {}
      closePath() {}
    },
  );
  const canvas = {
    ...listen,
    clientWidth: 400,
    clientHeight: 300,
    width: 0,
    height: 0,
    getContext: () => context,
  } as unknown as HTMLCanvasElement;
  const objects = {
    get: () => stored,
    keys: () => [stored.object.objectId][Symbol.iterator](),
    observe: () => () => undefined,
  } as unknown as LiveObjects;
  const source: DrawingSource = {
    view: () => undefined,
    commit: () => undefined,
    erase: () => undefined,
    objects,
    history: {
      undo: () => undefined,
      redo: () => undefined,
      checkpoint: () => undefined,
      canUndo: false,
      canRedo: false,
      observe: () => () => undefined,
    },
    awareness: undefined,
    close: () => Promise.resolve(),
  };

  const surface = createSurface(canvas, "board", source, () => ({
    size: "Medium",
    primary: 0,
    secondary: 4,
    mode: "Pencil",
  }));
  calls.length = 0;
  for (const callback of frames.splice(0)) callback(0);
  surface.dispose();

  expect(calls).toEqual([`fillRect ${PAPER}`, "fill #1f2328"]);
});
import type { BBox, Point } from "@stallion/geometry";
import { MAX_LEVEL, MIN_LEVEL } from "@stallion/geometry";

export type Camera = { x: number; y: number; zoom: number };

export const MIN_ZOOM = 2 ** -MAX_LEVEL;
export const MAX_ZOOM = 2 ** -MIN_LEVEL;

export const clampZoom = (zoom: number): number => Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, zoom));

export const screenToWorld = (camera: Camera, screen: Point): Point => ({
  x: camera.x + screen.x / camera.zoom,
  y: camera.y + screen.y / camera.zoom,
});

export const worldToScreen = (camera: Camera, world: Point): Point => ({
  x: (world.x - camera.x) * camera.zoom,
  y: (world.y - camera.y) * camera.zoom,
});

export const viewBounds = (camera: Camera, width: number, height: number): BBox => ({
  minX: camera.x,
  minY: camera.y,
  maxX: camera.x + width / camera.zoom,
  maxY: camera.y + height / camera.zoom,
});

export const pan = (camera: Camera, dx: number, dy: number): Camera => ({
  x: camera.x - dx / camera.zoom,
  y: camera.y - dy / camera.zoom,
  zoom: camera.zoom,
});

export const zoomTo = (camera: Camera, screen: Point, target: number): Camera => {
  const anchor = screenToWorld(camera, screen);
  const zoom = clampZoom(target);
  return { x: anchor.x - screen.x / zoom, y: anchor.y - screen.y / zoom, zoom };
};

export const zoomAt = (camera: Camera, screen: Point, factor: number): Camera =>
  zoomTo(camera, screen, camera.zoom * factor);

export type PinchStep = { anchor: Point; factor: number; dx: number; dy: number };

export const pinch = (camera: Camera, step: PinchStep): Camera =>
  pan(zoomAt(camera, step.anchor, step.factor), step.dx, step.dy);

export const wheelFactor = (deltaY: number, deltaMode: number): number => {
  const pixels = deltaMode === 1 ? deltaY * 16 : deltaMode === 2 ? deltaY * 800 : deltaY;
  return 2 ** (-pixels / 300);
};
