const browser = await chromium.launch({ headless: true });
const opts = { ...devices["Galaxy Tab S9"], extraHTTPHeaders: accessHeaders() };
const errors = [];
const open = async (name) => {
  const context = await browser.newContext(opts);
  const page = await context.newPage();
  page.on("console", (m) => {
    if (m.type() !== "error") return;
    if (/favicon/.test(m.location().url) || /favicon/.test(m.text())) return;
    errors.push(`${name}: ${m.text()}`);
  });
  page.on("pageerror", (e) => errors.push(`${name} pageerror: ${e.message}`));
  await page.goto(url);
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 20000 });
  await page.locator('.status[data-connection="Connected"]').waitFor({ timeout: 20000 });
  return page;
};
const shot = async (page, name) => {
