  writeFileSync(path, await page.screenshot());
  console.log(path);
};
const viewport = (page) =>
  page.evaluate((id) => {
    const cam = JSON.parse(localStorage.getItem(`stallion:camera:${id}`) ?? "null");
    const c = document.querySelector("canvas.surface");
    if (!cam || !c) return null;
    return { x: cam.x + c.clientWidth / 2 / cam.zoom, y: cam.y + c.clientHeight / 2 / cam.zoom, zoom: cam.zoom };
  }, boardId);
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const check = (ok, label) => {
  console.log(`${ok ? "PASS" : "FAIL"} ${label}`);
  if (!ok) process.exitCode = 1;
};

const a = await open("A");
const b = await open("B");
await a.waitForFunction(() => document.querySelectorAll(".presence .peer").length === 2, null, { timeout: 15000 });
await b.waitForFunction(() => document.querySelectorAll(".presence .peer").length === 2, null, { timeout: 15000 });
check(true, "both see two chips");
await shot(a, "1-a-two-chips");
await shot(b, "1-b-two-chips");

await a.getByRole("button", { name: "Pan tool" }).click();
await a.mouse.move(320, 600);
await a.mouse.down();
await a.mouse.move(200, 500, { steps: 10 });
await a.mouse.up();
await a.mouse.move(320, 600);
for (let i = 0; i < 4; i++) await a.mouse.wheel(0, -150);
await wait(800);
const va = await viewport(a);
console.log("A viewport", JSON.stringify(va));
await b.locator(".presence .peer:not([disabled])").click();
await wait(1500);
const vb = await viewport(b);
console.log("B viewport", JSON.stringify(vb));
check(
  va && vb && Math.abs(va.zoom - vb.zoom) / va.zoom < 0.01 && Math.abs(va.x - vb.x) < 2 && Math.abs(va.y - vb.y) < 2,
  "B camera matches A's viewport",
);
check(await b.locator(".follow-pill").isVisible(), "B shows the following pill");
check((await b.locator('.presence .peer[aria-pressed="true"]').count()) === 1, "B chip ringed");
await shot(b, "2-b-following");
await shot(a, "2-a-moved");

const cdp = await b.context().newCDPSession(b);
const pts = (d) => [
  { x: 320 - d, y: 600, id: 1, radiusX: 2, radiusY: 2 },
  { x: 320 + d, y: 600, id: 2, radiusX: 2, radiusY: 2 },
];
await cdp.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: pts(60) });
for (let d = 70; d <= 160; d += 10) {
  await cdp.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: pts(d) });
  await wait(16);
}
await cdp.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
await wait(600);
check(!(await b.locator(".follow-pill").isVisible()), "pinch stopped the follow (pill gone)");
check((await b.locator('.presence .peer[aria-pressed="true"]').count()) === 0, "ring gone");
const vb2 = await viewport(b);
console.log("B after pinch", JSON.stringify(vb2));
await shot(b, "3-b-after-pinch");
console.log(`console errors: ${errors.length}`);
for (const e of errors) console.log(`  ${e}`);
await browser.close();
EOF
